drag-affordance-cursor.js:
const root = document.querySelector('.fx-drag-affordance-cursor');
if (root) {
  const rail = root.querySelector('.fx-drag-affordance-cursor__rail');
  rail.addEventListener('keydown', event => { if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') { event.preventDefault(); rail.scrollBy({ left: event.key === 'ArrowLeft' ? -220 : 220, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' }); } });
  if (!matchMedia('(prefers-reduced-motion: reduce)').matches && matchMedia('(pointer: fine)').matches) {
    let start = 0; let origin = 0;
    rail.addEventListener('pointerdown', event => { start = event.clientX; origin = rail.scrollLeft; rail.dataset.dragging = 'true'; rail.setPointerCapture(event.pointerId); });
    rail.addEventListener('pointermove', event => { if (rail.hasPointerCapture(event.pointerId)) rail.scrollLeft = origin - (event.clientX - start); });
    const stop = event => { delete rail.dataset.dragging; if (rail.hasPointerCapture(event.pointerId)) rail.releasePointerCapture(event.pointerId); };
    rail.addEventListener('pointerup', stop); rail.addEventListener('pointercancel', stop);
  }
}

lens-zoom-hover.js:
const root = document.querySelector('.fx-lens-zoom-hover');
if (root && !matchMedia('(prefers-reduced-motion: reduce)').matches && matchMedia('(hover: hover) and (pointer: fine)').matches) {
  const stage = root.querySelector('.fx-lens-zoom-hover__stage');
  let frame = 0; let point = { x: 0, y: 0 };
  stage.addEventListener('pointerenter', () => { root.dataset.active = 'true'; });
  stage.addEventListener('pointermove', event => { point = { x: event.clientX, y: event.clientY }; if (!frame) frame = requestAnimationFrame(() => { const box = stage.getBoundingClientRect(); const x = Math.max(0, Math.min(box.width, point.x - box.left)); const y = Math.max(0, Math.min(box.height, point.y - box.top)); root.style.setProperty('--fx-x', x + 'px'); root.style.setProperty('--fx-y', y + 'px'); root.style.setProperty('--fx-image-x', 64 - x * 2 + 'px'); root.style.setProperty('--fx-image-y', 64 - y * 2 + 'px'); frame = 0; }); });
  stage.addEventListener('pointerleave', () => { delete root.dataset.active; });
}

